import logging
import six
import sys
import time
import traceback
from threading import Thread, Lock

from ta_ue_plugin_android.uepc.datatransfer.data_transfer_config import DataTransferConfig
from ta_ue_plugin_android.uepc.datatransfer.data_transfer_item import DataTransferItem, MAX_IPERF_INTERVALS_DELAY
from ta_ue_plugin_android.uepc.ue_manager_exceptions import DtOverNameException, DtNameNotFoundException, \
    CannotReleaseDtNotFinishedException, IperfServerStuckException, KillProcessFailException, CmdExecuteException
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class DataTransfersManager(object):
    """DataTransfersManager"""

    # pylint: disable=protected-access
    def __init__(self, ue_pool_on_server, ssh_manager):
        """

        :param ue_pool_on_server:
        :param ssh_manager:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        self.ue_pool_on_server = ue_pool_on_server
        self.dt_dict = {}
        self.dt_force_stopped = set()
        self.dt_thread = DataTransfersManagerThread()
        self.ssh_manager = ssh_manager

    def start_data_transfer(self, ue_sn, dt_name, dt_config):
        """Method's name says everything."""
        if isinstance(dt_config, dict):
            dt_config = self._new_dt_config(dt_name, dt_config)
            self.logger.debug('Data transfer config during start_data_transfer: {}'.format(dt_config.__dict__))
        if (ue_sn, dt_name) in self.dt_dict and (ue_sn, dt_name) not in self.dt_force_stopped:
            raise DtOverNameException("data transfer overname: %s on %s" % (dt_name, ue_sn))
        self._register_ssh_client(dt_config.app_server)
        uecontrol = self.ue_pool_on_server.get_ue(ue_sn)
        uecontrol._add_release_method(uecontrol.kill_process_with_phrase, 'iperf')
        dt_item = self._new_data_transfer_item(dt_config, uecontrol, dt_name=dt_name)
        dt_item.debug_desc = "{}, {}".format(ue_sn, dt_name)
        self.dt_thread.add_dt(dt_item)
        self.dt_dict[ue_sn, dt_name] = dt_item
        if (ue_sn, dt_name) in self.dt_force_stopped:
            self.dt_force_stopped.remove((ue_sn, dt_name))

    def _register_ssh_client(self, app_server):
        ip = app_server['host']
        user = app_server['user']
        password = app_server['password']
        self.ssh_manager.register(ip, user, password)

    def _new_dt_config(self, dt_name, dt_config):
        return DataTransferConfig(dt_name).init_me(**dt_config)

    def _new_data_transfer_item(self, dt_config, uecontrol, dt_name):
        return DataTransferItem(dt_config, uecontrol, self.ssh_manager, dt_name=dt_name)

    def add_to_force_stopped(self, ue_sn, dt_name):
        """Mark data transfer as force stopped, for example during stop_data_transfer, after releasing dt_item"""
        if (ue_sn, dt_name) in self.dt_dict:
            self.dt_force_stopped.add((ue_sn, dt_name))
        else:
            self.logger.debug('Data transfer {} stopped, finished or not started yet.'.format(dt_name),
                              extra={'ue_id': ue_sn})

    def is_data_transfer_finish(self, ue_sn, dt_name):
        """Method's name says everything."""
        self.logger.debug("Checking if data transfer {} is finished".format(dt_name), extra={'ue_id': ue_sn})
        if (ue_sn, dt_name) in self.dt_force_stopped:
            self.logger.debug("Data transfer {} was stopped".format(dt_name), extra={'ue_id': ue_sn})
            return True
        dt_item = self._get_dt_item(dt_name, ue_sn)
        if dt_item.has_raised:
            self.logger.debug("Data transfer {} raised exception".format(dt_name), extra={'ue_id': ue_sn})
            dt_item.raise_exception()
        if dt_item.is_finish():
            self.logger.debug("Data transfer {} finished".format(dt_name), extra={'ue_id': ue_sn})
            return True
        self.logger.debug("Data transfer {} is still running".format(dt_name), extra={'ue_id': ue_sn})
        return False

    def is_data_transfer_started(self, ue_sn, dt_name):
        """Checks if data transfer is started on client and server - client is started after server"""
        self.logger.debug('Checking if data transfer has started')
        dt_item = self._get_dt_item(dt_name, ue_sn)
        dt_item.raise_exception()
        return dt_item.is_iperf_client_started()

    def check_data_transfer(self, ue_sn, dt_name):
        """Checks if data transfer is progressing on client and/or server side"""
        validation_start_time = time.time()
        dt_item = self._get_dt_item(dt_name, ue_sn)
        iperf_interval = dt_item.dt_config.get_iperf_interval()
        max_time_without_output = float(iperf_interval) * float(MAX_IPERF_INTERVALS_DELAY) / 2.
        timeout = time.time() + max_time_without_output

        while time.time() < timeout:
            if self.is_data_transfer_finish(ue_sn, dt_name):
                self.logger.info('Skipping check. Data transfer {} is already finished.'.format(dt_name))
                return
            self.logger.debug("Check Data Transfer: awaiting new server output.")
            if not dt_item.last_server_read_time:
                self.logger.info("There is no server out yet. Unable to check data transfer")
                time.sleep(iperf_interval)
                continue
            server_out_active = dt_item.last_server_read_time > validation_start_time
            if server_out_active:
                self.logger.debug('Data transfer is alive!')
                return
            time.sleep(iperf_interval)
        raise IperfServerStuckException("Server didn't receive any data in {}s.\n"
                                        "Please check your network connectivity between client and server.\n"
                                        "Make sure UE didn't change IP address during data transfer.\n"
                                        "This is for data transfer name: {}"
                                        .format(max_time_without_output, dt_name))

    def _get_dt_item(self, dt_name, ue_sn):
        if (ue_sn, dt_name) not in self.dt_dict:
            raise DtNameNotFoundException("Can not find data transfer %s on UE %s" % (dt_name, ue_sn))
        return self.dt_dict[ue_sn, dt_name]

    def count_avg_throughput(self, ue_sn, dt_name, omit=0, end=0, tput_collection_src="iperf"):
        """Method's name says everything."""
        dt_item = self._get_dt_item(dt_name, ue_sn)
        rows = dt_item.get_rows_depending_on_traffic_type()
        if rows:
            return dt_item.count_avg_throughput(rows, omit, end, tput_collection_src)
        self.logger.debug("Data transfer is probably not started yet. Server reader didn't receive any iperf intervals yet")
        return None

    def get_datagram_loss(self, ue_sn, dt_name):
        """Method's name says everything."""
        dt_item = self._get_dt_item(dt_name, ue_sn)
        dt_item.count_datatransfer_statistics()
        return dt_item.datagram_loss

    def get_dt_reports(self, ue_sn, dt_name, tail=0):
        """Method's name says everything."""
        dt_item = self._get_dt_item(dt_name, ue_sn)
        if tail == 0:
            return dt_item.client_lines, dt_item.server_lines, dt_item.iperf_cmds
        return dt_item.client_lines[-tail:], dt_item.server_lines[-tail:], dt_item.iperf_cmds

    def get_data_transfer_statistics(self, dt_name, ue_sn):
        """
        Return string with dt statistics: avg,min,max;comma-delimited list of bits/s for all intervals
        :param dt_name: Data transfer name
        :param ue_sn: UE serial number
        :return: String: "avg,min,max;comma_delimited_list_of_bps_per_interval"
        """
        self.logger.debug("Getting data transfer statistics")
        dt_item = self._get_dt_item(dt_name, ue_sn)
        rows = dt_item.get_rows_depending_on_traffic_type()
        if rows:
            return dt_item.get_data_transfer_statistics(rows)
        self.logger.debug("Data transfer is probably not started yet. "
                          "Server reader didn't receive any iperf intervals yet")
        return str()

    def release_dt_name(self, ue_sn, dt_name, force_close=False):
        """Method's name says everything."""
        if self._is_dt_force_stopped(ue_sn, dt_name):
            self.logger.debug('Data transfer {} was already force stopped and is released.'.format(dt_name),
                              extra={'ue_id': ue_sn})
            return

        dt_item = self._get_dt_item(dt_name, ue_sn)
        if not dt_item.finish and not dt_item.has_raised:
            if not force_close:
                raise CannotReleaseDtNotFinishedException(
                    "Data transfer %s on UE %s, can not be released, not finished." % (dt_name, ue_sn))

        self.close_dt(ue_sn, dt_name, force_close)
        del self.dt_dict[ue_sn, dt_name]

    def close_dt(self, ue_sn, dt_name, force_close):
        dt_item = self._get_dt_item(dt_name, ue_sn)
        try:
            dt_item.close_dt_item()
        except KillProcessFailException as e:
            trace = traceback.format_exc()
            self.logger.warning(
                "Exception while closing DT {} on {}, exception is {} {}".format(dt_name, ue_sn, e, trace),
                extra={'ue_id': ue_sn})
            if not force_close:
                six.reraise(KillProcessFailException, e, trace)
        except CmdExecuteException as cmd_exception:
            trace = traceback.format_exc()
            self.logger.warning(
                "Exception while closing DT {} on {}, exception is {} {}".format(dt_name, ue_sn, cmd_exception, trace),
                extra={'ue_id': ue_sn})
            if not force_close:
                six.reraise(CmdExecuteException, cmd_exception, trace)

    def _is_dt_force_stopped(self, ue_sn, dt_name):
        return True if (ue_sn, dt_name) in self.dt_force_stopped else False

    def close_data_transfers_manager(self):
        """Stops thread and closes ssh sessions."""
        self.dt_thread.stop_data_transfer_thread()
        if self.dt_thread.is_alive():
            self.logger.debug("Waiting for data transfer Thread to finish.")
            self.dt_thread.join()
        self.ssh_manager.close_all_ssh_connections()

    def release_ue(self, ue_sn_to_release, force_close):
        """
        Release all dt on this UE
        :param ue_sn_to_release:
        :param force_close:
        :return:
        """
        for ue_sn, dt_name in list(self.dt_dict.keys()):
            self.logger.debug('Releasing data transfer {} on {} UE'.format(dt_name, ue_sn))
            if ue_sn == ue_sn_to_release:
                self.release_dt_name(ue_sn, dt_name, force_close)


class DataTransfersManagerThread(Thread):
    """DataTransfersManagerThread"""

    def __init__(self):
        """Basic initialization."""
        super(DataTransfersManagerThread, self).__init__(name='Android app Data Transfer Thread')
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        self.active_items = []
        self.to_add_active_items = []
        self.to_add_active_items_lock = Lock()
        self.dt_going = True

    def add_dt(self, dt_item):
        """Add new data item to be processing in thread 'Android app Data Transfer Thread"""
        self.logger.debug("add_dt, trying to get into lock")
        with self.to_add_active_items_lock:
            self.logger.debug("add_dt, success get into lock")
            self._ensure_alive()
            self.to_add_active_items.append(dt_item)
            self.logger.debug("add_dt, leaving lock")
        self.logger.debug("add_dt, finish")

    def run(self):
        """Run thread."""
        self.logger.debug("DataTransfersManagerThread thread started")
        try:
            while self.dt_going:
                self._run_step()
            self.logger.debug(
                "DataTransfersManagerThread thread: while loop finish, self.dt_going = {}".format(self.dt_going))
        except Exception as e:
            trace = traceback.format_exc()
            self.logger.warning("Got exception inside DataTransfersManagerThread {} {}".format(e, trace))
            raise
        finally:
            self.logger.debug("DataTransfersManagerThread thread finished")

    def stop_data_transfer_thread(self):
        """Stop thread in near future."""
        self.dt_going = False

    def _ensure_alive(self):
        if not self.is_alive():
            super(DataTransfersManagerThread, self).__init__(name='Android app Data Transfer Thread')
            self.dt_going = True
            self.start()

    def _run_step(self):
        to_remove = []
        for item in self.active_items:
            if item.finish or item.has_raised:
                self.logger.debug("item_finish: {}".format(self.active_items))
                to_remove.append(item)
            else:
                self._process_dt_item(item)

        self._remove_from_active_items(to_remove)
        self._add_items_to_processing_list()

    def _remove_from_active_items(self, to_remove):
        for item in to_remove:
            self.active_items.remove(item)

    def _add_items_to_processing_list(self):
        if not self.to_add_active_items:
            return
        with self.to_add_active_items_lock:
            while self.to_add_active_items:
                item = self.to_add_active_items.pop()
                self.active_items.append(item)
                self.logger.debug("Added data transfer to active_items {}".format(item.debug_desc))

    def _process_dt_item(self, item):
        try:
            self.logger.debug("starting processing dt item {}".format(item.debug_desc))
            start = time.time()
            item.process_data_transfer()
            end = time.time()
            self.logger.debug("finish processing dt item {}, it took {} sec".format(item.debug_desc, end - start))
        except Exception as e:  # pylint: disable=broad-except
            trace = traceback.format_exc()
            self.logger.warning("Got exception inside _process_dt_item {} {}".format(e, trace))
            a, b, c = sys.exc_info()
            self._save_item_exception(item, a, b, c)

    def _save_item_exception(self, item, a, b, c):
        item.save_exception(a, b, c)
